        CaptionLine(
          start: Duration(milliseconds: 444517),
          end: Duration(milliseconds: 448505),
          text: 'Suddenly someone beside Imaan whispered:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 448505),
          end: Duration(milliseconds: 450586),
          text: '“You should not be here.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 450586),
          end: Duration(milliseconds: 452783),
          text: 'A boy stood behind them.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 452783),
          end: Duration(milliseconds: 454864),
          text: 'He was about their age.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 454864),
          end: Duration(milliseconds: 460196),
          text:
              'Unlike everyone else, he was staring directly at Imaan and Akhlaq.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 461080),
          end: Duration(milliseconds: 463605),
          text: '“You can see us?” Imaan asked.',
        ),
        CaptionLine(
