      audioAsset:
          'assets/audio/en/ibrahim/05_the_king_who_could_not_move_the_sun.ogg',
      category: StoryCategory.prophets,
      description: 'Hazrat Ibrahim (A.S.) — episode 5 of 11.',
      captions: [
        CaptionLine(
          start: Duration(milliseconds: 0),
          end: Duration(milliseconds: 1574),
          text: 'Episode 5: The King Who Could Not Move the Sun',
        ),
        CaptionLine(
          start: Duration(milliseconds: 1574),
          end: Duration(milliseconds: 3154),
          text: 'The palace was impressive.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 3154),
          end: Duration(milliseconds: 5707),
          text: 'Guards stood everywhere.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 5707),
          end: Duration(milliseconds: 10325),
          text: 'People lowered their voices around the ruler.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 10325),
          end: Duration(milliseconds: 14147),
          text: 'At the centre of the hall stood Ibrahim (A.S.).',
        ),
        CaptionLine(
          start: Duration(milliseconds: 14386),
          end: Duration(milliseconds: 18327),
          text: 'The ruler disputed with him concerning Allah.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 18805),
          end: Duration(milliseconds: 23627),
          text: 'Ibrahim declared that his Lord gives life and causes death.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 23627),
          end: Duration(milliseconds: 25689),
          text: 'The ruler responded:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 25689),
          end: Duration(milliseconds: 28357),
          text: '“I give life and cause death.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 28357),
          end: Duration(milliseconds: 31329),
          text: 'People around him nodded quickly.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 32072),
          end: Duration(milliseconds: 33028),
          text: 'Akhlaq whispered:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 33028),
          end: Duration(milliseconds: 36637),
          text: '“They did not even think about what he said.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 36637),
          end: Duration(milliseconds: 44001),
          text:
              'Then Ibrahim (A.S.) moved the argument to something the ruler could not imitate.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 44001),
          end: Duration(milliseconds: 46777),
          text: 'Allah brings the sun from the east.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 46777),
          end: Duration(milliseconds: 49021),
          text: 'So bring it from the west.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 49021),
          end: Duration(milliseconds: 49881),
          text: 'Silence.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 49881),
          end: Duration(milliseconds: 52216),
          text: 'The ruler had no answer.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 52216),
          end: Duration(milliseconds: 56149),
          text: 'The Qur’an describes him as confounded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 56521),
          end: Duration(milliseconds: 59307),
          text: 'Akhlaq looked towards the morning light entering the palace.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 59307),
          end: Duration(milliseconds: 62827),
          text: 'The ruler could command guards.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 62827),
          end: Duration(milliseconds: 65357),
          text: 'He could control people around him.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 65357),
          end: Duration(milliseconds: 67793),
          text: 'But he could not command the sun.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 67793),
          end: Duration(milliseconds: 70562),
          text: 'The fifth mark began glowing.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 70562),
          end: Duration(milliseconds: 73907),
          text: 'The mysterious boy appeared again.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 73907),
          end: Duration(milliseconds: 84480),
          text: '“The mystery is not only the Compass,” he told them.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 84480),
          end: Duration(milliseconds: 90002),
          text: '“What is it?” Imaan asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 90002),
          end: Duration(milliseconds: 90003),
          text: '“What people do when truth threatens something they love.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 90003),
          end: Duration(milliseconds: 90173),
          text: 'The people with idols loved inherited beliefs.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 90173),
          end: Duration(milliseconds: 93113),
          text: 'The crowd loved belonging.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 93113),
          end: Duration(milliseconds: 96213),
          text: 'This ruler loved power.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 96213),
          end: Duration(milliseconds: 100805),
          text:
              'Then the hooded traveller appeared with something astonishing:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 100805),
          end: Duration(milliseconds: 102805),
          text: 'A second compass.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 102805),
          end: Duration(milliseconds: 105205),
          text: 'Its symbol was reversed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 105205),
          end: Duration(milliseconds: 108965),
          text: 'Its needle pointed directly towards the throne.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 108965),
          end: Duration(milliseconds: 111445),
          text: 'The children’s compass displayed:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 111445),
          end: Duration(milliseconds: 115765),
          text: 'DO NOT FOLLOW WHAT POINTS ONLY TO POWER.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 116530),
          end: Duration(milliseconds: 118169),
          text: 'Akhlaq almost chased the traveller.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 119043),
          end: Duration(milliseconds: 120245),
          text: 'Then stopped.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 120797),
          end: Duration(milliseconds: 121614),
          text: 'Imaan noticed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 121614),
