          text: 'THE NEXT DOOR WILL OPEN FOR A QUESTION ASKED BY A BELIEVER.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 152106),
          end: Duration(milliseconds: 155020),
          text: 'Ibn Kathir opened the passage.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 155020),
          end: Duration(milliseconds: 157082),
          text: 'Ibrahim (A.S.) asked Allah:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 157082),
          end: Duration(milliseconds: 160629),
          text: '“My Lord, show me how You give life to the dead.”',
        ),
