          text: 'Teach instead of laugh.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 194273),
          end: Duration(milliseconds: 197633),
          text: 'Include instead of command.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 197633),
          end: Duration(milliseconds: 201794),
          text: 'Help instead of humiliate.',
        ),
      ],
