          text: 'No fire burned.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 32509),
          end: Duration(milliseconds: 36549),
          text: 'Yet this journey felt difficult in another way.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 37002),
          end: Duration(milliseconds: 37909),
          text: 'Akhlaq looked back.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 38341),
          end: Duration(milliseconds: 42421),
          text: '“If the danger stopped, why not stay?”',
        ),
