          text: 'Imaan answered:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 43733),
          end: Duration(milliseconds: 48981),
          text: '“Because the problem was bigger than one dangerous moment.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 48981),
          end: Duration(milliseconds: 51861),
          text: 'The settlement became smaller.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 51861),
          end: Duration(milliseconds: 53541),
          text: 'Then disappeared.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 53541),
          end: Duration(milliseconds: 55398),
          text: 'Akhlaq realised:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 55398),
          end: Duration(milliseconds: 61110),
          text:
              '“For us this is an adventure. We know the Compass can take us back.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 61110),
          end: Duration(milliseconds: 63990),
          text: '“But Ibrahim was actually leaving.”',
