          text: '“Sometimes.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 72672),
          end: Duration(milliseconds: 75213),
          text: '“Then Ibrahim is losing?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 76390),
          end: Duration(milliseconds: 77533),
          text: 'Akhlaq looked at the road.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 78325),
