          text: 'Prophets.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 86145),
          end: Duration(milliseconds: 86618),
          text: 'The Ka‘bah.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 87405),
          end: Duration(milliseconds: 88822),
          text: 'A legacy of Tawheed.',
        ),
        CaptionLine(
