        CaptionLine(
          start: Duration(milliseconds: 115377),
          end: Duration(milliseconds: 117757),
          text: 'Imaan immediately recognised the trap.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 118309),
          end: Duration(milliseconds: 120709),
          text: 'Belonging was not wrong.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 120709),
          end: Duration(milliseconds: 123829),
          text: 'Adapting to harmless things was not wrong.',
        ),
