          start: Duration(milliseconds: 123829),
          end: Duration(milliseconds: 129669),
          text:
              'But if belonging required giving up what was right, the price had changed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 129669),
          end: Duration(milliseconds: 133109),
          text: 'The real Compass continued pointing forward.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 133109),
          end: Duration(milliseconds: 136789),
          text: 'Then they heard Ibrahim’s declaration of trust:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 137429),
          end: Duration(milliseconds: 142256),
          text: '“Indeed, I am going to my Lord. He will guide me.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 142256),
          end: Duration(milliseconds: 142666),
          text: 'Not:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 142666),
          end: Duration(milliseconds: 146212),
          text: '“I know exactly what will happen.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 146212),
          end: Duration(milliseconds: 146621),
          text: 'But:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 146621),
          end: Duration(milliseconds: 148250),
          text: 'Allah will guide me.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 148250),
          end: Duration(milliseconds: 150592),
          text: 'The seventh mark completed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 150694),
          end: Duration(milliseconds: 155703),
          text: 'The mysterious boy finally revealed something about himself.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 155703),
          end: Duration(milliseconds: 157981),
          text: '“This is where I turned back.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 158293),
          end: Duration(milliseconds: 161013),
          text: '“What do you mean?” Imaan asked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 161013),
          end: Duration(milliseconds: 165693),
          text: '“I reached a road where knowing the truth became expensive.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 165693),
          end: Duration(milliseconds: 167013),
          text: '“And?”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 167013),
          end: Duration(milliseconds: 169613),
          text: '“I chose what was familiar.”',
        ),
        CaptionLine(
