          text: 'The world faded.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 171573),
          end: Duration(milliseconds: 174373),
          text: 'The next scene showed a barren valley.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 174373),
          end: Duration(milliseconds: 175333),
          text: 'A mother.',
        ),
        CaptionLine(
