          text: 'Almost no water.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 180506),
          end: Duration(milliseconds: 181839),
          text: '“Hajar,” Imaan whispered.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 181839),
          end: Duration(milliseconds: 185245),
          text: '“And Ismail,” Akhlaq replied.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 186845),
          end: Duration(milliseconds: 191200),
          text: 'Challenge of the Day: Give Up One Wrong Comfort',
        ),
        CaptionLine(
          start: Duration(milliseconds: 191200),
          end: Duration(milliseconds: 197714),
          text:
              'Today, give up one comfort that is getting in the way of something right.',
        ),
        CaptionLine(
