        CaptionLine(
          start: Duration(milliseconds: 804),
          end: Duration(milliseconds: 3804),
          text: 'Episode 8: The Valley With Nothing',
        ),
        CaptionLine(
          start: Duration(milliseconds: 4276),
          end: Duration(milliseconds: 6616),
          text: 'The valley seemed empty.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 6616),
          end: Duration(milliseconds: 8116),
          text: 'Mountains.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 8116),
          end: Duration(milliseconds: 9616),
          text: 'Heat.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 9616),
          end: Duration(milliseconds: 11416),
          text: 'Bare earth.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 11416),
          end: Duration(milliseconds: 16436),
          text: 'Ibrahim (A.S.) stood with Hajar and the infant Ismail.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 16436),
          end: Duration(milliseconds: 19156),
          text: 'Then he began to leave.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 19156),
          end: Duration(milliseconds: 21036),
          text: 'Hajar followed him.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 21036),
          end: Duration(milliseconds: 26518),
          text:
              'Why was he leaving them in a valley without people or visible provision?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 26518),
          end: Duration(milliseconds: 29768),
          text: 'Then came her crucial question:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 29768),
          end: Duration(milliseconds: 33268),
          text: 'Had Allah commanded him to do this?',
        ),
        CaptionLine(
          start: Duration(milliseconds: 33268),
          end: Duration(milliseconds: 36858),
          text: 'When she learned that Allah had, she stopped.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 36858),
          end: Duration(milliseconds: 40249),
          text: 'Her answer carried extraordinary trust:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 40249),
          end: Duration(milliseconds: 43868),
          text: 'Then Allah will not neglect us.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 44260),
          end: Duration(milliseconds: 45803),
          text: 'The valley remained empty.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 45803),
          end: Duration(milliseconds: 49125),
          text: 'No miracle appeared immediately.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 49125),
          end: Duration(milliseconds: 61558),
          text:
              'Ibrahim (A.S.) later made dua, asking Allah regarding his family in the uncultivated valley near the Sacred House, prayer, provision and hearts inclined towards them.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 61558),
          end: Duration(milliseconds: 62623),
          text: 'Then he left.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 62623),
          end: Duration(milliseconds: 66856),
          text: 'The food and water eventually ran out.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 66856),
          end: Duration(milliseconds: 68220),
          text: 'Ismail cried.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 68220),
          end: Duration(milliseconds: 70700),
          text: 'Hajar did not simply sit.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 70700),
          end: Duration(milliseconds: 72932),
          text: 'She went towards Safa.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 72932),
          end: Duration(milliseconds: 73700),
          text: 'Looked.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 73700),
          end: Duration(milliseconds: 74724),
          text: 'Searched.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 74724),
          end: Duration(milliseconds: 75236),
          text: 'Then Marwah.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 76004),
          end: Duration(milliseconds: 77156),
          text: 'Back again.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 77156),
          end: Duration(milliseconds: 78436),
          text: 'Seven times.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 79076),
          end: Duration(milliseconds: 80228),
          text: 'Akhlaq whispered:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 80228),
          end: Duration(milliseconds: 82070),
          text: '“But she trusted Allah.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 82213),
          end: Duration(milliseconds: 82463),
          text: 'Imaan replied:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 84244),
          end: Duration(milliseconds: 88284),
          text: '“Maybe trusting Allah is why she can keep searching.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 88284),
          end: Duration(milliseconds: 89071),
          text: 'The compass displayed:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 89071),
          end: Duration(milliseconds: 91884),
          text: 'TAWAKKUL IS NOT WAITING WITHOUT EFFORT.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 91884),
          end: Duration(milliseconds: 93784),
          text: 'Then came relief.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 93784),
          end: Duration(milliseconds: 94884),
          text: 'Water.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 94884),
          end: Duration(milliseconds: 96084),
          text: 'Zamzam.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 96084),
          end: Duration(milliseconds: 98724),
          text: 'Hajar gathered the water carefully.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 98724),
          end: Duration(milliseconds: 101284),
          text: 'She drank and cared for her child.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 102070),
          end: Duration(milliseconds: 103484),
          text: 'Akhlaq whispered:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 104236),
          end: Duration(milliseconds: 108716),
          text: '“She trusted Allah before she could see the water.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 108716),
          end: Duration(milliseconds: 111036),
          text: 'That was the difference.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 111036),
          end: Duration(milliseconds: 114196),
          text: 'The mysterious boy appeared again.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 114196),
          end: Duration(milliseconds: 115756),
          text: 'He told them:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 115756),
          end: Duration(milliseconds: 123756),
          text:
              '“People like miracles because miracles arrive dramatically. But obedience often begins quietly.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 124661),
          end: Duration(milliseconds: 128728),
          text:
              'Imaan asked why he had turned back during the previous journey.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 128728),
          end: Duration(milliseconds: 129860),
          text: 'He answered:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 129860),
          end: Duration(milliseconds: 135408),
          text:
              '“Because I wanted Allah to show me the result before I obeyed.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 135408),
          end: Duration(milliseconds: 137928),
          text: 'Then he looked at Hajar.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 137928),
          end: Duration(milliseconds: 143808),
          text:
              '“She had certainty about Allah, not certainty about how the problem would be solved.”',
        ),
        CaptionLine(
          start: Duration(milliseconds: 143808),
          end: Duration(milliseconds: 147080),
          text: 'Later, people began approaching the valley.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 147080),
          end: Duration(milliseconds: 151240),
          text:
              'Life was beginning to grow where there had once seemed to be nothing.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 151240),
          end: Duration(milliseconds: 153480),
          text: 'The eighth mark completed.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 153480),
          end: Duration(milliseconds: 158520),
          text:
              'YOU DO NOT NEED TO SEE THE WHOLE ANSWER BEFORE TAKING THE RIGHT STEP.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 158520),
          end: Duration(milliseconds: 161680),
          text: 'TRUST ALLAH. THEN MOVE.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 161680),
          end: Duration(milliseconds: 163800),
          text: 'Back in the library, the journal wrote:',
        ),
        CaptionLine(
          start: Duration(milliseconds: 164212),
          end: Duration(milliseconds: 168852),
          text: 'NEXT, A HOUSE WILL RECEIVE VISITORS WHO REFUSE TO EAT.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 168852),
          end: Duration(milliseconds: 171572),
          text: 'The ninth mark began glowing.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 171572),
          end: Duration(milliseconds: 171573),
          text: 'Challenge of the Day: Make Dua, Then Take One Step',
        ),
        CaptionLine(
          start: Duration(milliseconds: 171573),
          end: Duration(milliseconds: 177412),
          text:
              'Choose one problem you have been worrying about instead of acting on.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 177412),
          end: Duration(milliseconds: 179495),
          text: 'Make sincere dua.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 180252),
          end: Duration(milliseconds: 183852),
          text: 'Then take one useful step.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 184204),
          end: Duration(milliseconds: 187811),
          text: 'Start the homework.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 187811),
          end: Duration(milliseconds: 190761),
          text: 'Apologise.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 190761),
          end: Duration(milliseconds: 194040),
          text: 'Ask for help.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 194040),
          end: Duration(milliseconds: 196663),
          text: 'Practise.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 196663),
          end: Duration(milliseconds: 198958),
          text: 'Prepare.',
        ),
        CaptionLine(
          start: Duration(milliseconds: 198958),
          end: Duration(milliseconds: 198959),
          text: 'Trust Allah and move.',
        ),
      ],
    ),
